import React from "react";
import {
  Container,
  Divider,
  Heading,
  Box,
  Text,
  Link as ChakraLink,
} from "@chakra-ui/react";
import { Layout } from "../components/layout";
import { StaticImage } from "gatsby-plugin-image";
import { Link, navigate } from "gatsby";

const About = () => {
  return (
    <Layout>
      <Box  pt={{base:5,md:10}}
        px={{base:0,md:8}}>
        <Heading
          mt={10}
          textAlign={"left"}
          fontSize="3xl"
          color={"black"}
          mb={6}
        >
          Hi!
        </Heading>
        <Text fontSize={"xl"} lineHeight={"8"}>
          Thanks for visiting my website.
        </Text>
        <br />
        <Text fontSize={"xl"} lineHeight={"8"}>
          Here you'll find a brief overview of my ideas and the things I enjoy
          doing—in other words, a little about who I am.
        </Text>
        <Divider mt={8} mb={6} />
        <Heading textAlign={"left"} fontSize="3xl" color={"black"} mb={6}>
          A 10-Second Bio
        </Heading>
        <Text fontSize={"xl"} lineHeight={"8"}>
         I'm Colombian.
        </Text>
        <br />
        <Text fontSize={"xl"} lineHeight={"8"}>
         I live in Soacha, Cundinamarca.
        </Text>
        <br />
        <Text fontSize={"xl"} lineHeight={"8"}>
         I work at <ChakraLink   target="_blank" color="secondary.500" href="https://lab.lapix.com.co/">Lapix</ChakraLink>.
        </Text>
        <br />
        <Text fontSize={"xl"} lineHeight={"8"}>
         What I enjoy most about software development is finding solutions to problems.
        </Text>
        <br />
        <Text fontSize={"xl"} lineHeight={"8"}>
         I practice track and field and mountain biking.
        </Text>
        <br />
        <Text fontSize={"xl"} lineHeight={"8"}>
        My favorite book is <em>A Common World</em> by Marina Garcés.
        </Text>
        <Divider mt={8} mb={6} />
        <Heading textAlign={"left"} fontSize="3xl" color={"black"} mb={6}>
          Contact Me
        </Heading>
        <Text fontSize={"xl"} lineHeight={"8"} mb={5}>
          I'm on <ChakraLink        _hover={{ color: "black" }}
            target="_blank" color="secondary.500" href="https://twitter.com/Will_i_am_dev">Twitter</ChakraLink> and <ChakraLink         _hover={{ color: "black" }}
            target="_blank" color="secondary.500" href="https://www.linkedin.com/in/william-melo-8701831b1/">LinkedIn</ChakraLink>. Feel free to follow me or send me a direct message.
        </Text>
      </Box>
    </Layout>
  );
};

export default About;
